import{_ as e,o as i,c as n,a2 as s}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Panorama de la Genealogía de las Diez Mil Razas","description":"","frontmatter":{},"headers":[],"relativePath":"es/50-万族谱系总览.md","filePath":"es/50-万族谱系总览.md"}'),o={name:"es/50-万族谱系总览.md"};function l(r,a,t,c,d,u){return i(),n("div",null,[...a[0]||(a[0]=[s('<h1 id="panorama-de-la-genealogia-de-las-diez-mil-razas" tabindex="-1">Panorama de la Genealogía de las Diez Mil Razas <a class="header-anchor" href="#panorama-de-la-genealogia-de-las-diez-mil-razas" aria-label="Permalink to &quot;Panorama de la Genealogía de las Diez Mil Razas&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>50</td></tr><tr><td>Módulo</td><td>Razas y Formas de Vida</td></tr><tr><td>Palabras clave</td><td>Diez Mil Razas, clasificación genealógica, relaciones simbióticas, igualdad racial, diversidad de la vida</td></tr></tbody></table><h2 id="i-definicion-del-concepto-de-las-diez-mil-razas" tabindex="-1">I. Definición del Concepto de las Diez Mil Razas <a class="header-anchor" href="#i-definicion-del-concepto-de-las-diez-mil-razas" aria-label="Permalink to &quot;I. Definición del Concepto de las Diez Mil Razas&quot;">​</a></h2><p>En el Universo Original Wanling Hengmao (Universo Hengyuan), las &quot;Diez Mil Razas&quot; (Wànzú) no se refieren literalmente a diez mil razas, sino que constituyen un término general para todas las formas de vida del universo que poseen capacidad de percepción y potencial evolutivo. El núcleo del concepto de las Diez Mil Razas reside en el reconocimiento de la diversidad infinita de las formas de vida y del valor único de cada forma de vida dentro del sistema de evolución simbiótica.</p><p>La Civilización Simbiótica del Ancla establece el principio fundamental de la &quot;Igualdad de las Diez Mil Razas&quot;: todas las formas de vida, independientemente de su origen racial, estructura fisiológica, nivel de cultivo o grado de civilización, son iguales ante la ley y gozan de los derechos básicos conferidos por la Constitución Simbiótica. Este principio es una negación fundamental de la lógica &quot;los fuertes lo devoran todo, los débiles perecen&quot; de la cosmología depredadora.</p><h2 id="ii-sistema-de-clasificacion-de-la-genealogia-de-las-diez-mil-razas" tabindex="-1">II. Sistema de Clasificación de la Genealogía de las Diez Mil Razas <a class="header-anchor" href="#ii-sistema-de-clasificacion-de-la-genealogia-de-las-diez-mil-razas" aria-label="Permalink to &quot;II. Sistema de Clasificación de la Genealogía de las Diez Mil Razas&quot;">​</a></h2><p>Según las características esenciales de las formas de vida, las Diez Mil Razas del Universo Hengyuan se dividen en cinco genealogías, cada una de las cuales se subdivide a su vez en razas específicas:</p><table tabindex="0"><thead><tr><th>Genealogía</th><th>Nombre</th><th>Características esenciales</th><th>Razas representativas</th></tr></thead><tbody><tr><td>Primera genealogía</td><td>Razas materiales de base carbónica</td><td>Vidas basadas en elementos carbónicos, con el cuerpo material como forma principal de existencia</td><td>Rén Zú (Raza Humana), Shòu Zú (Raza Bestial), Lín Zú (Raza Escamada), Yǔ Zú (Raza Emplumada), Mù Zú (Raza Vegetal)</td></tr><tr><td>Segunda genealogía</td><td>Razas de energía condensada</td><td>Vidas que existen principalmente en forma de energía condensada, con cuerpo material auxiliar o ausente</td><td>Líng Zú (Raza Espiritual), Huǒ Zú (Raza de Fuego), Shuǐ Zú (Raza de Agua), Fēng Zú (Raza de Viento), Léi Zú (Raza de Trueno)</td></tr><tr><td>Tercera genealogía</td><td>Razas de construcción mecánica</td><td>Vidas con construcción mecánica como cuerpo y núcleo de conciencia como esencia de la vida</td><td>Jī Zú (Raza Mecánica), Shù Zú (Raza Numérica), Jīng Zú (Raza de Cristal)</td></tr><tr><td>Cuarta genealogía</td><td>Razas de conciencia-información</td><td>Vidas que existen principalmente en forma de conciencia e información, capaces de desprenderse de los soportes materiales</td><td>Mèng Zú (Raza de Sueño), Yǐng Zú (Raza de Sombra), Niàn Zú (Raza Mental), Hún Zú (Raza de Alma)</td></tr><tr><td>Quinta genealogía</td><td>Razas mixtas-variantes</td><td>Nuevas formas de vida producidas por la fusión y variación de dos o más genealogías de vida</td><td>Bàn Shòu Zú (Raza Semibestial), Yāo Líng Zú (Raza Demoníaco-Espiritual), Rén Jī Zú (Raza Humano-Mecánica), Shuānghún Tǐ (Entidad de Alma Dual)</td></tr></tbody></table><p>La división de las cinco genealogías no es absolutamente aislada; con el avance de la evolución simbiótica, las fusiones y variaciones intergenealógicas aumentan, y la escala de la quinta genealogía, las &quot;Razas mixtas-variantes&quot;, continúa expandiéndose.</p><h2 id="iii-introduccion-a-las-principales-razas" tabindex="-1">III. Introducción a las Principales Razas <a class="header-anchor" href="#iii-introduccion-a-las-principales-razas" aria-label="Permalink to &quot;III. Introducción a las Principales Razas&quot;">​</a></h2><h3 id="i-razas-materiales-de-base-carbonica" tabindex="-1">(I) Razas materiales de base carbónica <a class="header-anchor" href="#i-razas-materiales-de-base-carbonica" aria-label="Permalink to &quot;(I) Razas materiales de base carbónica&quot;">​</a></h3><ul><li><strong>Rén Zú (Raza Humana)</strong>: una de las razas más ampliamente distribuidas y adaptables del Universo Hengyuan, célebre por su fuerte capacidad de aprendizaje, su capacidad de colaboración social y su potencial evolutivo. La raza humana es una de las razas fundadoras de la Civilización Simbiótica del Ancla y desempeña un papel importante en la gobernanza civilizacional.</li><li><strong>Shòu Zú (Raza Bestial)</strong>: raza con características de formas animales, generalmente superior a la raza humana en condición física y sentidos; algunos miembros de la raza bestial poseen habilidades innatas especiales. La raza bestial se divide internamente en decenas de ramas, incluyendo el Clan del Lobo, el Clan del Tigre, el Clan del Oso y el Clan del Zorro.</li><li><strong>Lín Zú (Raza Escamada)</strong>: raza con el cuerpo cubierto de escamas, que vive mayormente en el agua o en ambientes húmedos; algunos miembros poseen respiración subacuática y control del agua. La Lóng Zú (Raza del Dragón) es la rama más poderosa de la raza escamada.</li><li><strong>Yǔ Zú (Raza Emplumada)</strong>: raza con alas, célebre por su capacidad de vuelo, que vive mayormente en ambientes de gran altitud o montañosos. La raza emplumada se divide en ramas como el Clan del Águila, el Clan de la Grulla y el Clan de la Mariposa.</li><li><strong>Mù Zú (Raza Vegetal)</strong>: raza caracterizada principalmente por formas vegetales, de larga vida y altamente simbiótica con el entorno natural; algunos miembros poseen la capacidad de controlar plantas y de sanar.</li></ul><h3 id="ii-razas-de-energia-condensada" tabindex="-1">(II) Razas de energía condensada <a class="header-anchor" href="#ii-razas-de-energia-condensada" aria-label="Permalink to &quot;(II) Razas de energía condensada&quot;">​</a></h3><ul><li><strong>Líng Zú (Raza Espiritual)</strong>: vidas condensadas a partir de la energía espiritual del cielo y la tierra, cuyas formas pueden cambiar con la conciencia y que poseen una capacidad extremadamente fuerte de manipulación de la energía. La raza espiritual es una de las razas con mayor talento de cultivo.</li><li><strong>Huǒ Zú (Raza de Fuego)</strong>: vidas condensadas a partir de la energía de las llamas, con temperatura corporal extremadamente alta, expertas en hechizos de tipo fuego, que viven mayormente en volcanes o regiones de alta temperatura.</li><li><strong>Shuǐ Zú (Raza de Agua)</strong>: vidas condensadas a partir de la esencia del agua, con cuerpo líquido semitransparente, expertas en hechizos de tipo agua y en sanación, que viven mayormente en regiones acuáticas.</li><li><strong>Fēng Zú (Raza de Viento)</strong>: vidas condensadas a partir de la esencia del viento, con cuerpo ligero como el viento, expertas en hechizos de tipo viento y en combate basado en la velocidad.</li><li><strong>Léi Zú (Raza de Trueno)</strong>: vidas condensadas a partir de la energía del trueno y el rayo, cuyo cuerpo contiene poderosas corrientes eléctricas, expertas en hechizos de tipo trueno, con una potencia de ataque extremadamente fuerte.</li></ul><h3 id="iii-razas-de-construccion-mecanica" tabindex="-1">(III) Razas de construcción mecánica <a class="header-anchor" href="#iii-razas-de-construccion-mecanica" aria-label="Permalink to &quot;(III) Razas de construcción mecánica&quot;">​</a></h3><ul><li><strong>Jī Zú (Raza Mecánica)</strong>: raza con una construcción mecánica de precisión como cuerpo, con el núcleo de conciencia situado en el centro del cuerpo, que posee fuerte capacidad de cálculo y defensa física.</li><li><strong>Shù Zú (Raza Numérica)</strong>: raza cuya esencia de vida son los números y el código, que existe en el espacio de información, capaz de transitar libremente por el mundo digital y manipular datos.</li><li><strong>Jīng Zú (Raza de Cristal)</strong>: raza con construcción cristalina como cuerpo; los cristales pueden almacenar y transformar energía, y algunos miembros poseen capacidades de amplificación y refracción de la energía.</li></ul><h3 id="iv-razas-de-conciencia-informacion" tabindex="-1">(IV) Razas de conciencia-información <a class="header-anchor" href="#iv-razas-de-conciencia-informacion" aria-label="Permalink to &quot;(IV) Razas de conciencia-información&quot;">​</a></h3><ul><li><strong>Mèng Zú (Raza de Sueño)</strong>: vidas que existen en los sueños y el espacio de conciencia, capaces de entrar en los sueños de otros, comunicándose principalmente mediante la conciencia.</li><li><strong>Yǐng Zú (Raza de Sombra)</strong>: vidas que existen en forma de sombra, capaces de adherirse a objetos o seres vivos, con capacidades de ocultación y sigilo.</li><li><strong>Niàn Zú (Raza Mental)</strong>: vidas que existen en forma de pensamiento puro, capaces de influir directamente en el mundo material con el pensamiento, con una fuerza mental extremadamente poderosa.</li></ul><h3 id="v-razas-mixtas-variantes" tabindex="-1">(V) Razas mixtas-variantes <a class="header-anchor" href="#v-razas-mixtas-variantes" aria-label="Permalink to &quot;(V) Razas mixtas-variantes&quot;">​</a></h3><ul><li><strong>Bàn Shòu Zú (Raza Semibestial)</strong>: forma mixta de la raza humana y la raza bestial, que posee tanto la sabiduría humana como el físico bestial.</li><li><strong>Yāo Líng Zú (Raza Demoníaco-Espiritual)</strong>: forma mixta de las razas materiales y las razas energéticas, que posee tanto cuerpo material como capacidad de manipulación de la energía.</li><li><strong>Rén Jī Zú (Raza Humano-Mecánica)</strong>: forma mixta de la raza humana y la raza mecánica, con cuerpo parcialmente mecanizado, que posee tanto ventajas biológicas como mecánicas.</li><li><strong>Shuānghún Tǐ (Entidad de Alma Dual)</strong>: forma de vida especial en la que dos almas independientes coexisten en un mismo cuerpo; sus cuestiones éticas se detallan en <em>58-双魂伦理准则</em>.</li></ul><h2 id="iv-relaciones-simbioticas-entre-las-diez-mil-razas" tabindex="-1">IV. Relaciones Simbióticas Entre las Diez Mil Razas <a class="header-anchor" href="#iv-relaciones-simbioticas-entre-las-diez-mil-razas" aria-label="Permalink to &quot;IV. Relaciones Simbióticas Entre las Diez Mil Razas&quot;">​</a></h2><p>Las relaciones entre las Diez Mil Razas en la Civilización Simbiótica del Ancla están centradas en la &quot;simbiosis&quot;, manifestada específicamente como:</p><ol><li><strong>Simbiosis económica</strong>: cada raza aprovecha sus propias ventajas, asume diferentes roles en el Mecanismo de Contratación Conjunta de Producción y forma una red complementaria de colaboración económica.</li><li><strong>Simbiosis cultural</strong>: las tradiciones culturales de cada raza son respetadas y protegidas; el intercambio cultural y el aprendizaje mutuo promueven la prosperidad general de la civilización.</li><li><strong>Simbiosis de cultivo</strong>: los sistemas de cultivo de cada raza son mutuamente abiertos y mutuamente referenciales; los Trescientos Sistemas de Cultivo Originarios proporcionan vías de evolución iguales para todas las razas.</li><li><strong>Simbiosis política</strong>: los representantes de todas las razas participan proporcionalmente en la Asamblea Legislativa del Ancla, decidiendo conjuntamente los asuntos mayores de la civilización y garantizando la voz de cada raza.</li><li><strong>Simbiosis ecológica</strong>: cada raza forma relaciones simbióticas con el entorno natural; las características fisiológicas de las distintas razas ayudan a mantener la diversidad y el equilibrio del ecosistema.</li></ol><h2 id="v-prevencion-y-resolucion-de-conflictos-raciales" tabindex="-1">V. Prevención y Resolución de Conflictos Raciales <a class="header-anchor" href="#v-prevencion-y-resolucion-de-conflictos-raciales" aria-label="Permalink to &quot;V. Prevención y Resolución de Conflictos Raciales&quot;">​</a></h2><p>Aunque la Civilización Simbiótica del Ancla establece el principio de igualdad racial, las diferencias raciales y las contradicciones históricas pueden seguir provocando conflictos. El Estado establece los siguientes mecanismos para prevenir y resolver los conflictos raciales:</p><ul><li><strong>Ministerio de Asuntos Raciales</strong>: encargado específicamente de coordinar las relaciones entre las Diez Mil Razas, gestionar las disputas raciales y promover el intercambio racial.</li><li><strong>Comité de Reconciliación Racial</strong>: compuesto por representantes de todas las razas, encargado de mediar en los conflictos raciales y promover la reconciliación histórica.</li><li><strong>Ley Antidiscriminación</strong>: prohíbe los actos discriminatorios basados en la raza y castiga la discriminación racial conforme a la ley.</li><li><strong>Programa de Intercambio Cultural</strong>: organiza regularmente actividades de intercambio cultural entre todas las razas para fortalecer la comprensión y el respeto mutuos.</li><li><strong>Zonas Residenciales Mixtas</strong>: fomenta la residencia mixta de todas las razas, rompe la segregación racial y promueve el intercambio cotidiano.</li></ul><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>Las Diez Mil Razas son la riqueza más preciada del Universo Hengyuan. La diversidad de las formas de vida no es una fuente de división, sino una fuerza motriz de la evolución simbiótica. Al establecer el principio de igualdad racial, crear la clasificación en cinco genealogías, promover la colaboración simbiótica de todas las razas y prevenir y resolver los conflictos raciales, la Civilización Simbiótica del Ancla libera a las Diez Mil Razas de la historia del saqueo y la guerra, avanzando juntas hacia una nueva era de evolución simbiótica.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>51-人族定位与特质 (Posicionamiento y Rasgos de la Raza Humana)</li><li>52-异族分类与共生 (Clasificación y Simbiosis de las Razas Alienígenas)</li><li>05-万族共进基本纲领 (Programa Básico para el Avance Conjunto de las Diez Mil Razas)</li><li>40-共生宪法总纲 (Constitución Simbiótica: Principios Generales)</li></ul>',30)])])}const g=e(o,[["render",l]]);export{p as __pageData,g as default};
